SELECT
WHERE p.merchant_id = #{merchantId} AND p.is_deleted = 0
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.brand LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%') OR p.tea_tags LIKE CONCAT('%', #{keyword}, '%'))
AND p.category = #{category}
ORDER BY p.create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM products p WHERE p.merchant_id = #{merchantId} AND p.is_deleted = 0
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.brand LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%') OR p.tea_tags LIKE CONCAT('%', #{keyword}, '%'))
AND p.category = #{category}

SELECT 

WHERE p.merchant_id = #{merchantId}
  AND p.is_deleted = 0
  AND p.stock_quantity  <=  p.warning_stock
ORDER BY p.stock_quantity ASC, p.update_time DESC
LIMIT #{limit}
